import{_ as o,C as i,o as r,c as n,j as a,a as l,E as d,a6 as s}from"./chunks/framework.BHBQfcoO.js";const h="/releases/2026.10.0/chart.webp",c="/releases/2026.10.0/chart-studio.webp",u="/releases/2026.10.0/data-grid.webp",p="/releases/2026.10.0/processor-preview.webp",g="/releases/2026.10.0/template-sandbox.webp",m="/releases/2026.10.0/provenance.webp",y="/releases/2026.10.0/health-check.webp",k="/releases/2026.10.0/slider-drag-badge.webm",S=JSON.parse('{"title":"LCARdS 2026.10.0","description":"Charts and data grids rebuilt, a new look for Main Engineering and the studios, consistent colours, faster loading. Needs Home Assistant 2026.10.","frontmatter":{"version":"2026.10.0","status":"testing","summary":"Charts and data grids rebuilt, a new look for Main Engineering and the studios, consistent colours, faster loading. Needs Home Assistant 2026.10.","breaking":true,"notes_through":"3f70b3007746"},"headers":[],"relativePath":"releases/2026.10.0.md","filePath":"releases/2026.10.0.md"}'),f={name:"releases/2026.10.0.md"};function w(b,e,v,E,_,A){const t=i("ReleaseMeta");return r(),n("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-10-0",tabindex:"-1"},[l("LCARdS 2026.10.0 "),a("a",{class:"header-anchor",href:"#lcards-2026-10-0","aria-label":'Permalink to "LCARdS 2026.10.0"'},"​")],-1)),d(t),e[1]||(e[1]=s('<p>A big one. The chart and data grid cards are rebuilt from the ground up, every studio and Main Engineering panel now shares one look, and dashboards download a fraction of what they did. LCARdS now needs Home Assistant 2026.10.</p><ul><li><strong>Charts rebuilt:</strong> history, long-term statistics and data sources in one <code>sources:</code> list, time spans and grouping like apexcharts-card, and ApexCharts 7.</li><li><strong>Data grid rebuilt:</strong> conditional cell colours, header rows, tap actions and change highlights.</li><li><strong>Main Engineering and the studios:</strong> one consistent look, a live processor preview for data sources, a new template sandbox and a provenance inspector that shows where every value comes from.</li><li><strong>Colours that behave the same everywhere:</strong> every colour format works in every card, and alert modes recolour all of it at once.</li><li><strong>Faster:</strong> dashboards download about 420 KB instead of the whole 9 MB bundle; editors and the config panel load only when you open them.</li><li><strong>Help when something breaks:</strong> a health check and a prefilled bug report in the config panel.</li><li><strong>Docs you can play with:</strong> live cards, galleries and playgrounds on the docs site, and this new Releases section.</li></ul><h2 id="before-you-update" tabindex="-1">Before you update <a class="header-anchor" href="#before-you-update" aria-label="Permalink to &quot;Before you update&quot;">​</a></h2><ul><li><strong>Home Assistant 2026.10 or newer is required.</strong> On older versions the integration logs an error and does not load. Update Home Assistant first.</li><li><strong>Older chart and data grid configs keep working.</strong> They are converted in memory on your dashboard; nothing is saved. When you open one in the card editor, it shows the converted config and a notice: press Save to keep it, Cancel to leave your config as it was. See the <a href="/cards/chart/upgrading.html">chart</a> and <a href="/cards/data-grid/upgrading.html">data grid</a> upgrade pages for what changes.</li><li><strong>Rules: a plain-text <code>condition:</code> no longer matches.</strong> A condition such as <code>condition: light.desk is on</code> (no <code>[[[ ]]]</code> or <code>{{ }}</code>) used to count as true for every state. It now never matches and logs a warning. Wrap it as JavaScript or Jinja2; see <a href="/core/rules/conditions.html">rule conditions</a>.</li><li><strong>Rules: priority on cards now works the documented way round.</strong> Rules set on a card used to apply lower <code>priority</code> last, so it won. Now the higher priority wins, as the <a href="/core/rules/#priority">rules docs</a> say. If you tuned priorities to get the result you wanted, check them.</li><li><strong>Rules: <code>apply.profiles</code> is retired.</strong> It never had an effect; the editor now warns about it. Remove it from your rules.</li><li><strong>Elbow: a single <code>segment.color</code> value now applies.</strong> A plain colour (rather than a per-state map) was ignored and the theme colour showed instead. Elbows with one colour set will now show it.</li><li><strong>Data sources: the snake_case timing keys now apply.</strong> <code>window_seconds</code>, <code>min_emit_ms</code>, <code>coalesce_ms</code>, <code>max_delay_ms</code> and <code>emit_on_same_value</code> (what the data source editor writes) were ignored before. If you set them, your sources now update on that timing.</li></ul><h2 id="new-features" tabindex="-1">New features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New features&quot;">​</a></h2><h3 id="charts-rebuilt" tabindex="-1">Charts, rebuilt <a class="header-anchor" href="#charts-rebuilt" aria-label="Permalink to &quot;Charts, rebuilt&quot;">​</a></h3><p>Every series now lives in one <code>sources:</code> list, and each entry says where its data comes from: an entity&#39;s history, its long-term statistics, or an LCARdS data source.</p><img class="release-shot" alt="An area chart of two temperature sensors over 24 hours" src="'+h+`"><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-chart</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">chart_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">line</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">graph_span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">24h</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sensor.outdoor_temperature</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Outside</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sensor.indoor_temperature</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    statistics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">period</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hour</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Inside (hourly)</span></span></code></pre></div><ul><li><strong>Time like apexcharts-card:</strong> <code>graph_span</code>, span start, end and offset, and <code>group_by</code> (average, min, max, sum, median, delta and more, plus min/max bands, box plots and candlesticks).</li><li><strong>Several y axes</strong>, per-series units, precision, colours, line style and chart type.</li><li><strong>No point cap:</strong> charts fed by data sources were limited to 1000 points.</li><li><strong>Pie, donut, gauge, radar and treemap charts</strong> now plot each series&#39; latest value, so they render properly.</li><li><strong>ApexCharts 7</strong>, loaded only on pages that show a chart.</li><li><strong>Chart Studio:</strong> a new Time and axes section, a YAML tab with completion, and data source management inside the studio.</li></ul><img class="release-shot" alt="Chart Studio with the series editor and a live preview" src="`+c+'"><p>Coming from apexcharts-card? The <a href="/cards/chart/upgrading.html#coming-from-apexcharts-card">upgrade page</a> maps its options. Full details in <a href="/cards/chart/series.html">Series and time</a>, and try it in the <a href="/cards/chart/playground.html">chart playground</a>.</p><h3 id="data-grid-rebuilt" tabindex="-1">Data grid, rebuilt <a class="header-anchor" href="#data-grid-rebuilt" aria-label="Permalink to &quot;Data grid, rebuilt&quot;">​</a></h3><ul><li><strong>Conditional cell colours:</strong> colour a cell by its value or state.</li><li><strong>Header rows</strong>, <strong>tap actions on cells</strong>, column formats and a <code>refresh_cells</code> option.</li><li><strong>Change highlights:</strong> <code>highlight_changes</code> flashes cells when their value changes.</li><li><strong>Template and data source cells refresh</strong> reliably, and the Data Grid Studio adds, inserts and deletes columns correctly.</li></ul><img class="release-shot" alt="A data grid with a header row and cells coloured by state" src="'+u+'"><p>See <a href="/cards/data-grid/data.html">Data</a> and <a href="/cards/data-grid/styling.html">Styling</a>, or the <a href="/cards/data-grid/playground.html">data grid playground</a>.</p><h3 id="main-engineering-and-the-studios" tabindex="-1">Main Engineering and the studios <a class="header-anchor" href="#main-engineering-and-the-studios" aria-label="Permalink to &quot;Main Engineering and the studios&quot;">​</a></h3><p>Every studio (Chart, Data Grid, Layout, MSD, data sources, templates, provenance) now uses the same layout: tabs on the left, a live preview beside them, short help and the same buttons in the footer. Longer explanations sit in collapsible guides.</p><ul><li><strong>Data sources:</strong> a live preview runs your processors over the entity&#39;s real history and charts the result against the raw values. Processors are edited inline, in the order they run. &quot;Use in a chart&quot; copies a ready chart config for the source.</li></ul><img class="release-shot" alt="Data source dialog: two smoothing processors previewed against the raw history" src="'+p+'"> - **Templates:** each field with a template shows its live result. The new sandbox has completion for entities, attributes, data sources and theme tokens, test values and &quot;Save to field&quot;. <img class="release-shot" alt="Template sandbox with a Jinja2 template, its result and the entities it used" src="'+g+'"> - **Rules:** this card&#39;s rules edit as YAML with completion; new rules show at once, and edited ones say when a refresh is needed. - **Provenance:** pick any field to see how it got its value: your config, presets, theme tokens, templates and rules applying now. It updates live. <img class="release-shot" alt="Provenance inspector tracing a background colour to a theme token" src="'+m+'"> - **Theme:** the tokens this card uses, with their values, and links to the Theme Studio. - **Schema help in every YAML tab:** completion, hover descriptions, an &quot;Options here&quot; panel and links to the docs. <p>See <a href="/cards/main-engineering.html">Main Engineering</a>.</p><h3 id="support-and-system-info" tabindex="-1">Support and system info <a class="header-anchor" href="#support-and-system-info" aria-label="Permalink to &quot;Support and system info&quot;">​</a></h3><p>The config panel&#39;s Welcome tab now has a health check: Home Assistant version, frontend and integration versions matching, card-mod or UIX setup, leftover resources, the HA-LCARS theme and safe mode, each with a fix. <strong>Report an issue</strong> opens GitHub&#39;s bug form already filled in with your system info; you see exactly what is shared before you submit. See <a href="/getting-started/getting-help.html">Getting help</a>.</p><img class="release-shot" alt="The Support and system info health check" src="'+y+'"><h3 id="slider-drag-value-badge" tabindex="-1">Slider: drag value badge <a class="header-anchor" href="#slider-drag-value-badge" aria-label="Permalink to &quot;Slider: drag value badge&quot;">​</a></h3><p>While you drag a slider, a small badge follows your finger with the value it will set, like Home Assistant&#39;s own sliders. Colours, size, number format and how it fades out are configurable. See <a href="/cards/slider-card/#drag-value-badge">Drag value badge</a>.</p>',31)),e[2]||(e[2]=a("p",null,[a("video",{class:"release-shot",src:k,title:"A slider showing its value badge while dragged",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[3]||(e[3]=s('<h3 id="live-docs" tabindex="-1">Live docs <a class="header-anchor" href="#live-docs" aria-label="Permalink to &quot;Live docs&quot;">​</a></h3><p>The docs now render real LCARdS cards. Examples for buttons, elbows, sliders, select menus, charts and data grids are live; card pages have galleries of every preset and style; each card has a playground with completion and Copy YAML; and the <a href="/core/datasources/processor-reference.html">processor reference</a> runs each processor over sample data.</p><h2 id="improvements" tabindex="-1">Improvements <a class="header-anchor" href="#improvements" aria-label="Permalink to &quot;Improvements&quot;">​</a></h2><ul><li><strong>Colours, one set of rules:</strong> every colour field in every card accepts the same formats: hex, any CSS colour name, <code>rgb()</code> and <code>hsl()</code> in comma or space syntax, <code>oklch()</code>, <code>color-mix()</code>, CSS variables, theme tokens and the colour functions (<code>alpha</code>, <code>darken</code>, <code>lighten</code>, <code>saturate</code>, <code>desaturate</code>, <code>mix</code>, <code>base</code>). Functions nest, such as <code>alpha(darken(var(--lcards-orange), 0.2), 0.5)</code>, and a plain colour works the same as a state map. See <a href="/core/colours.html#colour-value-formats">Colours</a>.</li><li><strong>Alert modes recolour everything at once:</strong> cards repaint while the alert transition is still running, so the new palette is already there when it clears. That includes charts, MSD lines and shapes, data grid cascades and background animations, which used to keep the old colours until something redrew them.</li><li><strong><code>base()</code> everywhere:</strong> alert-proof colours now also work in animation and effect settings.</li><li><strong>Faster dashboards:</strong> about 420 KB to download instead of the whole 9 MB bundle. Card editors, the config panel and the Theme Studio load when you open them, and the files are served compressed.</li><li><strong>Dialogs inside Home Assistant:</strong> entity pickers and other HA controls in LCARdS dialogs work again (for example &quot;New from Entity&quot; in the Chart Studio).</li><li><strong>Overlays:</strong> cards shown in alert, connection or portal overlays stay live on pages without LCARdS cards, and their actions (more-info and so on) reach Home Assistant.</li><li><strong>Layout view:</strong> rows collapse for every kind of visibility condition set in HA&#39;s Visibility tab, and no longer recalculate on every state change.</li><li><strong>Data sources</strong> load history at full resolution first (hourly statistics only when there is none), and wait for Home Assistant before loading on a cold start.</li><li><strong>No emoji or em dashes</strong> in the editors; messages are shorter and use Home Assistant&#39;s own dialogs.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><details class="details custom-block"><summary>All fixes</summary><ul><li><strong>Button:</strong> colour animations on the button background and border now play (<a href="https://github.com/snootched/lcards/issues/401" target="_blank" rel="noreferrer">#401</a>).</li><li><strong>Rules:</strong> rules on a card stopped applying after Home Assistant moved the card (edit mode, layout changes, navigation); <code>entity_attr</code> conditions never matched; JavaScript conditions read the previous state; JavaScript and Jinja2 conditions didn&#39;t react to their entities; <code>condition: |</code> blocks broke JavaScript parsing.</li><li><strong>Templates:</strong> inline <code>{theme:...}</code> tokens rendered empty; a label mixing <code>{token}</code> and <code>{{ jinja }}</code> lost the Jinja2 part.</li><li><strong>Charts:</strong> month names were garbled (&quot;May&quot; became &quot;5ay&quot;); custom tooltips were invisible; gradients, legend and label font sizes and annotation colours were ignored; long decimals on the y axis; statistics charts squeezed every column to a hairline; charts stopped after leaving and returning to a view.</li><li><strong>Data sources:</strong> statistics and smoothing ignored <code>input_source</code>; an expression listed before its sources read nothing; <code>attribute: state</code> series were empty; new sources from the editor found no history.</li><li><strong>Data grid:</strong> card size errors, cells escaped twice, animations leaking after the card was removed.</li><li><strong>Slider:</strong> units for lights, covers, fans, humidifiers and valves default to %, and units show for non-numeric entities.</li><li><strong>Layout card:</strong> the Layout Studio&#39;s grid tools were missing on a fresh page.</li><li><strong>Colours:</strong> a new slider or button reported false &quot;Format validation failed&quot; warnings; <code>mix()</code> colours were flagged as invalid; nested colour functions (including the documented <code>alpha(base(...))</code>) and theme tokens inside a function did not work; a colour function written as a plain value reached charts unevaluated; <code>theme:darken(...)</code> in card config was never evaluated; <code>darken()</code>, <code>lighten()</code> and <code>saturate()</code> dropped transparency; <code>base()</code> followed the alert for theme colours defined with <code>color-mix()</code> or a colour name.</li><li><strong>Validation:</strong> chart series names with a dot (such as <code>statistics.min</code>) were reported as missing entities.</li><li><strong>Shape textures:</strong> a colour template could not return a colour function or theme token, and <code>match-light</code> only worked for <code>color</code>.</li><li><strong>Editors:</strong> several icon buttons had no icon, and colour chips showed as deselected when re-clicked.</li></ul></details>',6))])}const C=o(f,[["render",w]]);export{S as __pageData,C as default};
